#!/usr/bin/env python3
"""Regenerate the default Chisel CPU in a temporary directory; compare exact bytes.

This checks current-source delivery consistency, not historical v13 equivalence.
No comments, whitespace, source locations or diagnostic strings are filtered.
"""
import argparse
import difflib
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess
import sys
import tempfile

ROOT = Path(__file__).resolve().parents[2]
# Use the course parser, including its filelist-relative path and duplicate checks.
sys.path.insert(0, str(ROOT / "scripts"))
from build import read_sources

VERSIONS = {"sbt": "1.10.2", "scala": "2.13.12", "chisel": "6.5.0", "firtool": "1.62.0"}
FIRTOOL_HEADER = "// Generated by CIRCT firtool-" + VERSIONS["firtool"]


def project_versions(root):
    project = root / "dual-issue-chisel"
    build = (project / "build.sbt").read_text()
    patterns = {"scala": r'ThisBuild / scalaVersion := "([^"]+)"',
                "chisel": r'val chiselVersion = "([^"]+)"'}
    patterns["sbt"] = r"^sbt\.version=(\S+)$"
    found = {}
    for key, pattern in patterns.items():
        text = (project / "project/build.properties").read_text() if key == "sbt" else build
        match = re.search(pattern, text, re.M)
        if not match:
            raise ValueError(f"Cannot find the pinned {key} version in the project build configuration")
        found[key] = match.group(1)
    for key, value in found.items():
        if value != VERSIONS[key]:
            raise ValueError(f"{key}: project specifies {value}, CI pins {VERSIONS[key]}; review the toolchain pin before upgrading")
    return dict(VERSIONS)


def delivery_files(root):
    delivery = root / "dual-issue-chisel/rtl"
    course = read_sources(root / "verilog/filelist.f")
    native = read_sources(delivery / "filelist.f")
    if course != native:
        raise ValueError(f"Course filelist and native Chisel filelist disagree:\n  course={course}\n  native={native}")
    if not all(path.is_relative_to(delivery) for path in course):
        raise ValueError(f"Default course entry must use native dual-issue Chisel delivery: {course}")
    return [*course, delivery / "elaboration.json"]


def compare_delivery(root, generated, report):
    rows = []
    for committed in delivery_files(root):
        relative = committed.relative_to(root / "dual-issue-chisel/rtl")
        actual = generated / relative
        if not actual.is_file():
            raise ValueError(f"Generator did not emit course artifact {relative}: {actual}")
        expected = committed.read_bytes()
        data = actual.read_bytes()
        if not data:
            raise ValueError(f"Generator emitted empty course artifact: {relative}")
        if committed.suffix in (".sv", ".v") and data.splitlines()[0].decode() != FIRTOOL_HEADER:
            raise ValueError(f"{relative}: expected {FIRTOOL_HEADER!r}, got {data.splitlines()[0]!r}")
        same = expected == data
        row = {"path": str(committed.relative_to(root)), "equal": same,
               "committed_sha256": hashlib.sha256(expected).hexdigest(),
               "generated_sha256": hashlib.sha256(data).hexdigest()}
        rows.append(row)
        if same:
            print(f"PASS: {row['path']} is byte-identical ({row['generated_sha256']})", flush=True)
            continue
        diff = "".join(difflib.unified_diff(expected.decode().splitlines(keepends=True),
                                           data.decode().splitlines(keepends=True),
                                           fromfile="committed/" + str(relative),
                                           tofile="regenerated/" + str(relative)))
        diff_path = report / (str(relative).replace("/", "_") + ".diff")
        diff_path.write_text(diff)
        copy = report / "regenerated" / relative
        copy.parent.mkdir(parents=True, exist_ok=True)
        copy.write_bytes(data)
        row["diff"] = str(diff_path)
        print(f"FAIL: {row['path']} differs; complete diff: {diff_path}", file=sys.stderr)
        print("".join(diff.splitlines(keepends=True)[:100]), file=sys.stderr)
    return rows


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo-root", type=Path, default=ROOT)
    parser.add_argument("--report-dir", type=Path, default=Path("build/ci/chisel-consistency"))
    parser.add_argument("--sbt", default=os.environ.get("SBT", "sbt"), help="sbt executable (one path/name)")
    args = parser.parse_args()
    root = args.repo_root.resolve()
    report = (root / args.report_dir).resolve()
    report.mkdir(parents=True, exist_ok=True)
    result = {"check": "default dual-issue Chisel regeneration", "comparison": "exact bytes; no normalization", "status": "fail"}
    try:
        result["versions"] = project_versions(root)
        delivery_files(root)  # Fail before generation if the course entry moved.
        env = dict(os.environ)
        # Let Chisel 6.5.0 resolve its pinned Maven firtool 1.62.0, not a host override.
        env.pop("CHISEL_FIRTOOL_PATH", None)
        with tempfile.TemporaryDirectory(prefix="pararisc-chisel-ci-") as temporary:
            generated = Path(temporary) / "rtl"
            command = [args.sbt, "-batch", f'run --out "{generated}"']
            result["command"] = command
            print(f"Generating from dual-issue-chisel/src into {generated}", flush=True)
            log = report / "generate.log"
            with log.open("w") as output:
                proc = subprocess.run(command, cwd=root / "dual-issue-chisel", env=env,
                                      stdout=output, stderr=subprocess.STDOUT)
            if proc.returncode:
                print("".join(log.read_text().splitlines(keepends=True)[-100:]), file=sys.stderr)
                raise ValueError(f"sbt exited {proc.returncode}; full generation log: {log}")
            result["artifacts"] = compare_delivery(root, generated, report)
            if not all(row["equal"] for row in result["artifacts"]):
                raise ValueError("Scala and committed course artifacts are out of sync; regenerate and review the delivery diff")
            result["status"] = "pass"
    except (OSError, ValueError) as error:
        result["error"] = str(error)
        print(f"ERROR: {error}", file=sys.stderr)
    finally:
        (report / "result.json").write_text(json.dumps(result, indent=2) + "\n")
    return 0 if result["status"] == "pass" else 1


if __name__ == "__main__":
    sys.exit(main())
